import { test, expect, totp, secret, enterOtp } from '../../src/fixtures.ts';

test('Filter and sort an account transaction grid', async ({ page }) => {
  await test.step('Open the app', async () => {
    await page.goto('/');
  });

  await test.step('Sign in', async () => {
    await page.getByLabel('Username', { exact: true }).fill(secret('teller_user'));
    await page.getByLabel('Password', { exact: true }).fill(secret('teller_pass'));
    await page.getByRole('button', { name: 'Sign in', exact: true }).click();
  });

  await test.step('Pass MFA', async () => {
    await enterOtp(page.getByRole('textbox'), totp(secret('teller_totp')));
    await page.getByRole('button', { name: 'Verify', exact: true }).click();
  });

  await test.step('Open account', async () => {
    await page.getByRole('table', { name: 'Customer accounts', exact: true }).waitFor({ state: 'visible' });
    await page.getByRole('link', { name: 'Everyday Checking', exact: true }).click();
    await page.getByRole('table', { name: 'Transactions', exact: true }).waitFor({ state: 'visible' });
  });

  await test.step('Filter', async () => {
    await page.getByLabel('Category', { exact: true }).selectOption({ label: 'Groceries' });
    await page.getByRole('status').waitFor({ state: 'visible' });
    await expect(page.getByRole('status')).toContainText('transactions');
  });

  await test.step('Sort by amount', async () => {
    await page.getByRole('button', { name: 'Amount', exact: true }).click();
    await expect(page.getByRole('columnheader', { name: 'Amount', exact: true })).toBeVisible();
  });
});
